
CREATE TABLE recorded_lessons(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),module_id uuid NOT NULL,created_by uuid NOT NULL REFERENCES users(id),title text NOT NULL,description text NOT NULL DEFAULT '',youtube_video_id text NOT NULL CHECK(youtube_video_id ~ '^[A-Za-z0-9_-]{11}$'),lesson_date date,duration_seconds int CHECK(duration_seconds>0),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(batch_id,module_id) REFERENCES modules(batch_id,id));
CREATE TABLE useful_links(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),module_id uuid,created_by uuid NOT NULL REFERENCES users(id),title text NOT NULL,url text NOT NULL,description text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(batch_id,module_id) REFERENCES modules(batch_id,id));
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),created_by uuid NOT NULL REFERENCES users(id),title text NOT NULL,description text NOT NULL DEFAULT '',location text NOT NULL DEFAULT '',starts_at timestamptz NOT NULL,ends_at timestamptz,cover_image_key text,visibility text NOT NULL DEFAULT 'MEMBERS_ONLY' CHECK(visibility IN ('PUBLIC','MEMBERS_ONLY')),status text NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED','ARCHIVED')),published_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at IS NULL OR ends_at>=starts_at));
CREATE TABLE batch_profiles(batch_id uuid PRIMARY KEY REFERENCES batches(id),headline text NOT NULL DEFAULT '',about_text text NOT NULL DEFAULT '',mission_text text NOT NULL DEFAULT '',contact_email text NOT NULL DEFAULT '',hero_image_key text,updated_by uuid REFERENCES users(id),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE batch_positions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL REFERENCES batches(id),title text NOT NULL,description text NOT NULL DEFAULT '',sort_order int NOT NULL DEFAULT 0,is_public boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(batch_id,id));
CREATE TABLE position_assignments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),batch_id uuid NOT NULL,position_id uuid NOT NULL,user_id uuid NOT NULL,starts_at timestamptz NOT NULL,ends_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(batch_id,position_id) REFERENCES batch_positions(batch_id,id),FOREIGN KEY(batch_id,user_id) REFERENCES batch_memberships(batch_id,user_id),CHECK(ends_at IS NULL OR ends_at>=starts_at));
